/* PoolMarshall owner toolkit. Independent implementation from public feature descriptions. */
(function(){'use strict';function boot(){const app=window.Poolside;if(!app)return;const $=id=>document.getElementById(id),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),M=window.PoolMath;
const state=()=>app.state;const now=()=>new Date().toLocaleDateString('en-CA'),stamp=()=>new Date().toISOString(),uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random();
state().care??={version:1,active:'main',profiles:[{id:'main',name:'Houston pool',type:'Pool',gallons:18000,sanitizer:'Other / unknown',finish:'Unknown',targets:{},lookback:30}],buckets:{},products:[],transactions:[],reminders:[],equipment:[],feeders:[],meters:[],treatments:[],timers:[]};const C=()=>state().care,P=()=>C().profiles.find(p=>p.id===C().active)||C().profiles[0];const mine=list=>(list||[]).filter(x=>x.pool===P().id);const store=()=>{app.save();render();};
const safeNumber=v=>v!==''&&v!=null&&Number.isFinite(Number(v));const num=(id,min=-Infinity,max=Infinity)=>M.number($(id).value,$(id).previousElementSibling?.textContent||id,min,max);const panel=(title,body)=>`<div class="panel"><h2>${title}</h2>${body}</div>`;
const field=(name,label,type='text',value='',attrs='')=>`<div><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${E(value)}" ${attrs}></div>`;
const select=(name,label,items,value)=>`<div><label for="${name}">${label}</label><select id="${name}" name="${name}">${items.map(i=>`<option ${value===i?'selected':''}>${E(i)}</option>`).join('')}</select></div>`;
const button=(action,id,label)=>`<button type="button" data-action="${action}" data-id="${E(id)}">${label}</button>`;
const fmt=(v,places=2)=>Number.isFinite(Number(v))?Number(v).toLocaleString(undefined,{maximumFractionDigits:places}):'Unknown';const currency=v=>v==null?'Unpriced':'$'+Number(v).toFixed(2);
const list=(items,empty)=>items.length?items.join(''):`<div class="empty">${empty}</div>`;
const dateAdd=(date,days)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+Number(days));return d.toLocaleDateString('en-CA')};
const perPool=[['tasks',{}],['logs',[]],['findings',[]]];
function switchPool(id){if(id===C().active)return;C().buckets[C().active]=Object.fromEntries(perPool.map(([k])=>[k,JSON.parse(JSON.stringify(state()[k]))]));const bucket=C().buckets[id]||{};for(const [k,initial]of perPool)state()[k]=bucket[k]||JSON.parse(JSON.stringify(initial));C().active=id;document.querySelectorAll('[data-circuit]').forEach(b=>b.disabled=true);$('connectionText').textContent='Hardware bridge belongs to the original Houston pool. Refresh there after verification.';app.save();app.render();render();}
const tests=()=>state().logs.filter(l=>l.kind==='Water test').sort((a,b)=>String(b.logdate).localeCompare(String(a.logdate)));
const fields=[['fc','Free chlorine','ppm'],['tc','Total chlorine','ppm'],['br','Bromine','ppm'],['ph','pH',''],['ta','Total alkalinity','ppm as CaCO₃'],['ch','Calcium hardness','ppm as CaCO₃'],['cya','Cyanuric acid','ppm'],['temp','Temperature','°F'],['salt','Salt','ppm'],['tds','TDS','ppm'],['borate','Borates','ppm as B'],['magnesium','Magnesium hardness','ppm as CaCO₃'],['psi','Filter pressure','psi']];
function latest(key,lookback=true){const t=tests();if(!t.length)return null;const ref=new Date(t[0].logdate);for(let i=0;i<t.length;i++){if(i>0&&(!lookback||!['cya','ch','salt','tds','borate','magnesium'].includes(key)))break;const l=t[i];if(safeNumber(l[key])&&ref-new Date(l.logdate)>=0&&(ref-new Date(l.logdate))/864e5<=Number(P().lookback||30))return {value:Number(l[key]),date:l.logdate,basis:i?'Prior test':'Latest test'};}return null;}
function bounds(key){const custom=P().targets?.[key];if(custom&&safeNumber(custom.min)&&safeNumber(custom.max))return {...custom,basis:'Your target'};if(key==='ph')return {min:7,max:7.8,basis:'CDC reference'};if(key==='br'&&P().sanitizer==='Bromine')return {min:3,max:8,basis:'CDC typical reference; verify product label'};if(key==='fc'&&P().sanitizer==='Chlorine')return {min:P().type==='Spa'?3:(latest('cya')?.value===0?1:2),max:4,basis:'CDC reference minimum / typical upper range; verify CYA and product limits'};return null;}
function reportText(){return P().name+' · water report\n'+fields.map(([k,n,u])=>{const r=latest(k);return n+': '+(r?fmt(r.value)+' '+u+' ('+r.basis+', '+r.date+')':'Unknown')}).join('\n')+'\nPlanning report only; no swimming-safety certification.'}
function report(){const t=tests();return `<p>${t[0]?'Latest test '+E(t[0].logdate.replace('T',' ')):'No water test recorded.'} · Prior values are never substituted for current pH or sanitizer.</p><div class="reportgrid">${fields.map(([k,n,u])=>{const r=latest(k),b=bounds(k),out=r&&b&&(r.value<Number(b.min)||r.value>Number(b.max));return `<div class="reportcard"><div class="statusrow"><h3>${n}</h3><span class="badge ${out?'warn':''}">${!r?'Unknown':out?'Review':'Recorded'}</span></div><strong>${r?fmt(r.value):'—'} <small>${u}</small></strong><p class="subtle">${r?E(r.basis+' · '+r.date):'A measurement is needed'}</p>${b?`<p class="subtle">${E(b.basis)}: ${b.min}–${b.max}</p>`:'<p class="subtle">No target configured</p>'}${r&&b?`<meter min="${Math.min(0,b.min)}" max="${Math.max(Number(b.max)*1.5,r.value,1)}" low="${b.min}" high="${b.max}" optimum="${(Number(b.min)+Number(b.max))/2}" value="${r.value}"></meter>`:''}</div>`}).join('')}</div><p class="inline-note">These ranges are reference or user-selected values. High CYA, contamination, product limits, or stale tests need additional assessment. The app does not declare water safe to swim.</p><div class="actions">${button('share-report','','Share / copy report')}${button('export-tests','','Export tests CSV')}${button('tool','profiles','Edit targets')}</div>`;}
const menus=[['report','Water report'],['trends','Trends & history'],['supplies','Supplies & costs'],['treatments','Treatments'],['reminders','Reminders'],['equipment','Equipment & feeders'],['calculators','Calculators'],['wateruse','Water use & timers'],['weather','Weather & guidance'],['profiles','Pools & targets'],['coverage','Feature coverage']];
const style=document.createElement('style');style.textContent=`.tooltop{display:flex;align-items:center;gap:12px;margin-bottom:20px}.tooltop select{max-width:380px}.reportgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.reportcard{background:#041329;border:1px solid var(--line);padding:18px;border-radius:13px}.reportcard strong{font-size:25px}.reportcard strong small{font-size:10px;color:var(--muted)}.reportcard meter{width:100%;height:10px}.reportcard h3{font-size:13px}.reportcard .statusrow{align-items:flex-start}.tool-list .row{align-items:center}.tool-list .row p{font-size:12px}.tool-list .actions{margin:0}.tool-form{margin:18px 0}.tool-form .fields{grid-template-columns:repeat(2,minmax(0,1fr))}.trend{width:100%;height:220px;display:block;background:#041329;border-radius:14px}.scrolltable{overflow-x:auto}.tooltoolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.tooltoolbar select{width:auto}.photo{max-width:180px;max-height:120px;border-radius:8px}.pillgroup{display:flex;gap:8px;flex-wrap:wrap}.toolstatus{color:var(--teal);font-size:13px;min-height:24px}body:has(#tools:not(.hidden)) .hero{display:none}.toolheader{margin-left:auto;min-width:46px}.toolheader small{display:none}header>small{margin-left:0}.total{font-size:32px;letter-spacing:-1px}.toolnote{font-size:12px}.badgedate{font-size:10px;color:var(--muted)}@media(max-width:760px){.reportgrid{grid-template-columns:1fr 1fr}.reportcard{padding:13px}.reportcard strong{font-size:22px}.reportcard .statusrow{display:block}.tool-form .fields{grid-template-columns:1fr}.tooltop{display:block}.tooltop select{max-width:none}.tool-list .row .actions{margin-left:42px}.toolheader{font-size:11px;padding:8px}header>small{display:none}.reportcard h3{font-size:12px}.tooltoolbar{align-items:stretch}.tooltoolbar select{flex:1;min-width:100px}}`;document.head.append(style);
const sec=document.createElement('section');sec.id='tools';sec.className='view hidden';sec.innerHTML=`<div class="tooltop"><div style="flex:1"><div class="eyebrow">OWNER TOOLKIT</div><h2 style="margin-top:7px">Test. Care. Keep track.</h2></div><select id="toolSelect" aria-label="Choose pool care tool">${menus.map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select></div><div class="panel tooltoolbar"><label for="activePool" style="margin:0">Pool / spa</label><select id="activePool"></select><span class="subtle" id="poolSize"></span></div><div id="toolContent"></div><p id="toolMessage" class="toolstatus" role="status"></p>`;document.querySelector('main').insertBefore(sec,document.querySelector('.backup'));
const headerButton=document.createElement('button');headerButton.className='toolheader';headerButton.textContent='Care toolkit';headerButton.onclick=()=>openTool('report');document.querySelector('header').insertBefore(headerButton,document.querySelector('header>small'));
const homeLink=document.createElement('div');homeLink.className='panel';homeLink.innerHTML='<div class="panelhead"><div><span class="eyebrow">EXPANDED POOL CARE</span><h2 style="margin-top:8px">Your care toolkit</h2><p>Water reports, supply costs, treatments, reminders, and more.</p></div><button id="openToolkit" class="primary">Open toolkit</button></div><div id="toolHomeDue" class="subtle"></div>';$('overview').prepend(homeLink);$('openToolkit').onclick=()=>openTool('report');
function openTool(id){$('toolSelect').value=id;app.tab('tools');render()}
$('toolSelect').onchange=render;$('activePool').onchange=e=>switchPool(e.target.value);
// Extend manual tests; a photo is a record, not a calibrated strip reading.
const extra=document.createElement('div');extra.innerHTML=`<details><summary>Complete water test & photo</summary><div class="fields">${[['tc','Total chlorine (ppm)'],['br','Bromine (ppm)'],['ta','Total alkalinity (ppm as CaCO₃)'],['ch','Calcium hardness (ppm as CaCO₃)'],['salt','Salt (ppm)'],['tds','TDS (ppm)'],['borate','Borates (ppm as elemental B)'],['magnesium','Magnesium hardness (ppm as CaCO₃)']].map(([k,n])=>field(k,n,'number','','min="0" step="0.1"')).join('')}${select('method','Test method',['Unknown','DPD / drop kit','Photometer','Test strip','Other'])}</div><label for="testPhoto">Test-strip / water photo (manual record only)</label><input id="testPhoto" type="file" accept="image/*" capture="environment"><input id="photo" type="hidden"><p id="photoMessage" class="subtle">No automated chemistry interpretation. Enter measured results manually.</p></details>`;$('logForm').insertBefore(extra,$('logForm').firstChild);
$('testPhoto').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/'))return message('Choose an image file.');try{const bitmap=await createImageBitmap(f),canvas=document.createElement('canvas'),ratio=Math.min(1,640/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const value=canvas.toDataURL('image/jpeg',.65);bitmap.close();if(value.length>250000)throw Error('Photo too large after resizing. Choose a smaller image.');$('photo').value=value;$('photoMessage').textContent='Photo attached. Readings must still be entered manually.';}catch(err){$('photoMessage').textContent=err.message}};
$('logForm').addEventListener('submit',()=>setTimeout(()=>{render();$('photoMessage').textContent='No automated chemistry interpretation. Enter measured results manually.'},0));
const waterSummary=document.createElement('div');waterSummary.className='panel';waterSummary.innerHTML='<div class="statusrow"><h2>Water report & trends</h2><button id="waterReportOpen">View report</button></div><p id="waterSummary"></p>';$('water').prepend(waterSummary);$('waterReportOpen').onclick=()=>openTool('report');
function message(s){$('toolMessage').textContent=s}
function saveText(filename,text,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows){return rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n')}
function table(headers,rows){return `<div class="scrolltable"><table><thead><tr>${headers.map(h=>`<th>${E(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function monthsTransactions(){const month=now().slice(0,7);return mine(C().transactions).filter(t=>t.kind==='Use'&&t.date.startsWith(month))}
function profileView(){return panel('Pools, spas & targets',`<p>Care records switch with the selected body of water. The Jandy hardware bridge remains assigned to the original Houston pool only.</p><form id="profileForm" class="tool-form"><div class="fields">${field('profileName','Name','text',P().name,'required')}${field('profileGallons','Volume (US gallons)','number',P().gallons,'required min="1"')}${select('profileType','Body of water',['Pool','Spa'],P().type)}${select('profileSanitizer','Sanitizer',['Chlorine','Bromine','Other / unknown'],P().sanitizer)}${select('profileFinish','Surface',['Unknown','Plaster / pebble','Vinyl','Fiberglass','Tile','Other'],P().finish)}${field('lookback','Lookback for slow-changing tests (days)','number',P().lookback||30,'min="1" max="90" required')}</div><p class="subtle">Volume is user-provided, not measured by the app. No equipment inspection is implied.</p><h3>Custom target ranges</h3><p class="subtle">Blank fields retain the clearly labeled reference or unknown range. Select targets using your pool, test method, product labels, and equipment guidance.</p>${table(['Parameter','Minimum','Maximum','Preferred'],fields.filter(([k])=>!['psi','temp','magnesium','borate','tds','tc'].includes(k)).map(([k,n])=>[E(n),`<input name="target-${k}-min" type="number" step="0.1" aria-label="${n} minimum" value="${E(P().targets?.[k]?.min??'')}">`,`<input name="target-${k}-max" type="number" step="0.1" aria-label="${n} maximum" value="${E(P().targets?.[k]?.max??'')}">`,`<input name="target-${k}-preferred" type="number" step="0.1" aria-label="${n} preferred" value="${E(P().targets?.[k]?.preferred??'')}">`]))}<button class="primary">Save profile & targets</button></form><details><summary>Add another pool or spa</summary><form id="newProfileForm" class="tool-form"><div class="fields">${field('newName','Name','text','','required')}${field('newGallons','Volume (US gallons)','number','','min="1" required')}${select('newType','Body',['Pool','Spa'],'Pool')}</div><button>Add profile</button></form></details>`)}
function supplies(){const tx=monthsTransactions(),priced=tx.filter(t=>t.unitCost!=null),cost=priced.reduce((s,t)=>s+t.amount*t.unitCost,0);return panel('Supplies & monthly costs',`<div class="eyebrow">${now().slice(0,7)} · RECORDED USAGE</div><div class="total">${currency(cost)}</div><p>${tx.length} usage entries · ${tx.length-priced.length} unpriced. This total excludes missing prices, power, water, and fixed costs.</p><div class="tool-list">${list(mine(C().products).map(p=>{const use=tx.filter(t=>t.product===p.id),used=use.reduce((s,t)=>s+t.amount,0),pcost=use.filter(t=>t.unitCost!=null).reduce((s,t)=>s+t.amount*t.unitCost,0);return `<div class="row"><div class="body"><h3>${E(p.name)} <span class="badge ${p.quantity<=p.threshold?'warn':''}">${p.quantity<=p.threshold?'Restock':'In stock'}</span></h3><p>${fmt(p.quantity)} ${E(p.unit)} remaining · ${E(p.location||'Location unknown')}</p><p>Month: ${fmt(used)} ${E(p.unit)} used · ${use.some(t=>t.unitCost!=null)?currency(pcost):'Cost unknown'}${use.some(t=>t.unitCost==null)?' (partly unpriced)':''}</p><p>${E(p.ingredient||'Ingredient unspecified')}${p.strength?' · '+E(p.strength)+'%':''}</p></div><div class="actions">${button('use-product',p.id,'Log use')}${button('restock-product',p.id,'Restock')}${button('edit-product',p.id,'Edit')}</div></div>`}), 'No supplies recorded. Add the products you actually have.')}</div><details><summary>Add a supply</summary><form id="productForm" class="tool-form"><div class="fields">${field('productName','Product name','text','','required')}${select('productUnit','Stock unit',['g','kg','mL','L','oz by weight','fl oz','lb','each'],'each')}${field('quantity','Current stock','number','','required min="0" step="0.01"')}${field('threshold','Restock at or below','number',0,'required min="0" step="0.01"')}${field('location','Storage location')}${field('ingredient','Active ingredient')}${field('strength','Label strength (%)','number','','min="0" max="100" step="0.01"')}${field('packSize','Package amount in stock units','number','','min="0.001" step="0.001"')}${field('price','Package price ($), blank if unknown','number','','min="0" step="0.01"')}</div><button class="primary">Add supply</button></form></details><div class="actions">${button('export-costs','','Export usage & cost CSV')}</div><p class="subtle">Prices are captured at the time usage is logged. Product strength is a user-entered label value, not laboratory verification.</p>`)}
function treatments(){return panel('Treatment plan & progress',`<p>Track your label-based plan, sequence, amount added, circulation notes, and retesting. Nothing dispenses chemicals or certifies swim readiness.</p><div class="tool-list">${list(mine(C().treatments).map(t=>`<div class="row"><div class="body"><h3>${E(t.title)} <span class="badge">${E(t.status)}</span></h3><p>Step ${t.order} · ${fmt(t.added)} / ${fmt(t.planned)} ${E(t.unit)} added · ${fmt(Math.max(0,t.planned-t.added))} remaining</p><progress max="${t.planned}" value="${t.added}" style="width:100%"></progress><p>${E(t.product||'No product specified')} · ${E(t.date)}</p><p>${E(t.instructions)}</p><p>Retest: ${E(t.retest||'Not scheduled; check label')} · Next chemical: ${E(t.wait||'Label-specific; unknown')}</p></div><div class="actions">${button('advance-treatment',t.id,'Log progress')}${button('retest-treatment',t.id,'Mark retested')}</div></div>`),'No treatment plans. Use measured results and the exact product label before planning.')}</div><details open><summary>Add a treatment step</summary><form id="treatmentForm" class="tool-form"><div class="fields">${field('treatmentTitle','Purpose / parameter','text','','required')}${field('treatmentProduct','Exact product / label')}${field('planned','Planned quantity','number','','required min="0.001" step="0.001"')}${select('treatmentUnit','Unit',['g','kg','mL','L','oz by weight','fl oz','lb','each'],'g')}${field('order','Sequence number','number',1,'required min="1"')}${field('retest','Retest date & time','datetime-local')}${field('wait','Next-chemical wait / label instruction')}</div><label for="instructions">Separation, circulation & expected change from label</label><textarea id="instructions" name="instructions" required></textarea><button class="primary">Create treatment step</button></form></details><p class="inline-note">Never mix chlorine products with acid or other pool chemicals. Follow the label for addition order, separation, circulation, retest, and swimming restrictions. Time elapsed alone does not mean the water is safe.</p><a href="https://www.cdc.gov/healthy-swimming/media/pdfs/Pool-Chemical-Safety-USE-poster-p.pdf" target="_blank" rel="noreferrer">CDC chemical handling reference</a>`)}
function reminders(){return panel('Reminders',`<p>Due dates and repeat intervals are checked when this app is open. Export to your calendar for reminders outside the app; this is not a background push service.</p><div class="tool-list">${list(mine(C().reminders).map(r=>`<div class="row"><div class="body"><h3>${E(r.title)} <span class="badge ${r.due<=now()?'warn':''}">${r.due<=now()?'Due':'Scheduled'}</span></h3><p>${E(r.due)}${r.repeat?' · Repeats '+r.repeat+' days after completion':''}</p><p>${E(r.notes)}</p></div><div class="actions">${button('complete-reminder',r.id,'Complete')}${button('snooze-reminder',r.id,'+7 days')}${button('calendar-reminder',r.id,'Calendar')}</div></div>`),'No reminders yet.')}</div><form id="reminderForm" class="tool-form"><div class="fields">${field('reminderTitle','Task','text','','required')}${field('reminderDue','Due date','date',now(),'required')}${field('repeat','Repeat days, 0 for once','number',0,'min="0" required')}${field('reminderNotes','Notes')}</div><button class="primary">Add reminder</button></form>`)}
function equipment(){return panel('Equipment, warranties & feeders',`<div class="tool-list">${list(mine(C().equipment).map(q=>`<div class="row"><div class="body"><h3>${E(q.name)} <span class="badge">${E(q.condition)}</span></h3><p>${E(q.model)} · Serial ${E(q.serial||'unknown')}</p><p>Installed ${E(q.installed||'unknown')} · Warranty ends ${E(q.warranty||'unknown')}</p><p>Clean filter baseline: ${q.baseline!==''?E(q.baseline)+' psi':'unknown'}</p><p>${E(q.notes)}</p>${q.manual?`<a href="${E(q.manual)}" target="_blank" rel="noreferrer">Equipment documentation</a>`:''}</div>${button('equipment-note',q.id,'Add service note')}</div>`),'No inspected equipment records. The PS6 and pump model supplied earlier do not establish condition.')}</div><details><summary>Add equipment</summary><form id="equipmentForm" class="tool-form"><div class="fields">${field('equipmentName','Equipment','text','','required')}${field('model','Model')}${field('serial','Serial number')}${field('installed','Install date','date')}${field('warranty','Warranty end','date')}${field('baseline','Verified clean filter pressure (psi)','number','','min="0" step="0.1"')}${field('manual','Manual URL','url')}${select('condition','Condition',['Unknown / not inspected','Inspected, no issue observed','Needs verification','Confirmed issue'],'Unknown / not inspected')}</div><label for="equipmentNotes">Notes</label><textarea id="equipmentNotes" name="equipmentNotes"></textarea><button>Add equipment</button></form></details><h3 style="margin-top:22px">Feeder settings history</h3><p class="subtle">Manual history only; settings entered here do not program equipment.</p>${table(['Date','Feeder','Setting','Notes'],mine(C().feeders).slice().reverse().slice(0,20).map(f=>[E(f.date),E(f.name),E(f.setting),E(f.notes)]))}<form id="feederForm" class="tool-form"><div class="fields">${field('feederName','Feeder / chlorinator','text','','required')}${field('feederSetting','Setting with units','text','','required')}${field('feederDate','Date','date',now(),'required')}${field('feederNotes','Notes')}</div><button>Record setting</button></form><p class="subtle">Use Trends to compare feeder history with sanitizer readings and filter-maintenance logs.</p>`)}
function trends(){const key=$('trendParam')?.value||'fc',days=Number($('trendDays')?.value||30),start=Date.now()-days*864e5;const points=tests().filter(t=>safeNumber(t[key])&&new Date(t.logdate)>=start).reverse();const vals=points.map(t=>Number(t[key]));const low=Math.min(...vals),high=Math.max(...vals),first=points.length?new Date(points[0].logdate).getTime():0,last=points.length?new Date(points.at(-1).logdate).getTime():1;const xy=points.map(t=>[40+(new Date(t.logdate)-first)/Math.max(1,last-first)*720,170-(Number(t[key])-low)/Math.max(1,high-low)*130]);const line=points.length?`<svg class="trend" viewBox="0 0 800 220" role="img" aria-label="Recorded water readings over time"><path d="M40 20V180H770" fill="none" stroke="#456584"/><polyline points="${xy.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#00d0f0" stroke-width="3"/>${xy.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="5" fill="#ffd21b"><title>${E(points[i].logdate)}: ${vals[i]}</title></circle>`).join('')}<text x="42" y="205" fill="#a9c3db" font-size="12">${E(points[0].logdate.slice(0,10))}</text><text x="650" y="205" fill="#a9c3db" font-size="12">${E(points.at(-1).logdate.slice(0,10))}</text><text x="5" y="30" fill="#a9c3db" font-size="11">${fmt(high)}</text><text x="5" y="175" fill="#a9c3db" font-size="11">${fmt(low)}</text></svg>`:'<div class="empty">No readings in this time window.</div>';return panel('Trends & complete history',`<div class="tooltoolbar"><select id="trendParam" aria-label="Trend parameter">${fields.map(([k,n])=>`<option value="${k}" ${key===k?'selected':''}>${n}</option>`).join('')}</select><select id="trendDays" aria-label="Trend date range">${[7,30,90,365].map(d=>`<option value="${d}" ${d===days?'selected':''}>${d} days</option>`).join('')}</select></div><p class="subtle">Measured values only; lines join observations and do not infer intermediate readings.</p>${line}${table(['Date','Value','Method'],points.map(t=>[E(t.logdate),E(t[key]),E(t.method||'Unknown')]))}<details><summary>Maintenance & feeder overlays in this period</summary>${table(['Date','Event','Notes'],[...state().logs.filter(l=>l.kind!=='Water test').map(l=>({date:l.logdate,event:l.kind,notes:l.lognotes})),...mine(C().feeders).map(f=>({date:f.date,event:f.name+' · '+f.setting,notes:f.notes}))].filter(x=>new Date(x.date)>=start).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>[E(x.date),E(x.event),E(x.notes)]))}</details><details><summary>Extended tests & photos</summary>${list(tests().slice(0,20).map(t=>`<div class="tip"><strong>${E(t.logdate)}</strong><p>${fields.filter(([k])=>safeNumber(t[k])).map(([k,n,u])=>E(n+': '+t[k]+' '+u)).join(' · ')}</p>${typeof t.photo==='string'&&/^data:image\/jpeg;base64,/.test(t.photo)?`<img class="photo" src="${E(t.photo)}" alt="User-recorded pool or test-strip photo">`:''}</div>`),'No water tests recorded.')}</details>`)}
function calculators(){const calc=$('calcType')?.value||'volume';const menus=[['volume','Pool volume'],['dry','Dry chlorine, salt or CYA'],['label','Product-label ppm dose'],['replacement','Water replacement'],['saturation','Saturation / adjusted LSI'],['flow','Fill time']];const settings={volume:`${select('shape','Shape',['rectangle','oval'],'rectangle')}${field('length','Length (feet)','number','','required min="0.1" step="0.1"')}${field('width','Width (feet)','number','','required min="0.1" step="0.1"')}${field('shallow','Shallow depth (feet)','number','','required min="0.1" step="0.1"')}${field('deep','Deep depth (feet)','number','','required min="0.1" step="0.1"')}`,dry:`${select('doseParam','Measured parameter',['Free chlorine (available chlorine basis)','Salt','Cyanuric acid'],'Free chlorine (available chlorine basis)')}${field('doseGallons','US gallons','number',P().gallons,'required min="1"')}${field('currentPPM','Current (ppm)','number','','required min="0" step="0.1"')}${field('targetPPM','Chosen target (ppm)','number','','required min="0" step="0.1"')}${field('purity','Label active purity / available chlorine (%)','number','','required min="0.01" max="100" step="0.01"')}`,label:`${field('labelGallons','Label pool volume (US gallons)','number',10000,'required min="1"')}${field('labelAmount','Label product amount','number','','required min="0.001" step="0.001"')}${field('labelUnit','Label amount unit','text','','required')}${field('labelChange','Label ppm rise','number','','required min="0.001" step="0.001"')}${field('desiredChange','Chosen ppm rise','number','','required min="0" step="0.001"')}`,replacement:`${field('replaceCurrent','Current concentration (ppm)','number','','required min="0" step="0.1"')}${field('replaceSource','Fill-water concentration (ppm)','number','','required min="0" step="0.1"')}${field('replacePercent','Water replaced (%)','number',25,'required min="0" max="100" step="1"')}`,saturation:`${field('lsiPH','Measured pH','number',latest('ph')?.value??'','required min="6" max="9" step="0.01"')}${field('lsiTemp','Measured temperature (°F)','number',latest('temp')?.value??'','required min="32" max="110" step="0.1"')}${field('lsiCH','Measured calcium hardness (ppm)','number',latest('ch')?.value??'','required min="1" step="1"')}${field('lsiTDS','Measured TDS (ppm), includes salt','number',latest('tds')?.value??'','required min="1" step="1"')}${field('lsiTA','Measured total alkalinity (ppm)','number',latest('ta')?.value??'','required min="1" step="1"')}${field('lsiCYA','Measured CYA (ppm); enter 0 if verified absent','number',latest('cya')?.value??'','required min="0" step="1"')}${field('lsiCA','Optional independently corrected carbonate alkalinity','number','','min="1" step="0.1"')}${select('lsiBorates','Borate status',['Unknown','Verified absent','Present; corrected alkalinity entered'],'Unknown')}`,flow:`${field('fillGallons','Amount to fill (US gallons)','number','','required min="1"')}${field('fillGPM','Measured fill rate (gallons/minute)','number','','required min="0.01" step="0.01"')}`};return panel('Calculators',`<select id="calcType" aria-label="Calculator">${menus.map(([id,n])=>`<option value="${id}" ${calc===id?'selected':''}>${n}</option>`).join('')}</select><form id="calculatorForm" class="tool-form" data-kind="${calc}"><div class="fields">${settings[calc]}</div><button class="primary">Calculate estimate</button></form><div id="calcResult" class="notice">No result until the required inputs are provided.</div><p class="subtle">Volume and chemistry inputs are user-provided. Results are estimates, not instructions to add chemicals. Check product labels, test limits, surface/equipment constraints, and retest.</p>${calc==='dry'?'<p class="inline-note">Dry products only. Strength is percent by mass of available chlorine, sodium chloride, or CYA as selected. Not for liquid bleach, bromine, acid, alkalinity, or calcium products. No liquid-volume conversion without verified density.</p>':''}${calc==='label'?'<p class="inline-note">Use only a label direction that states a ppm rise for a known pool volume. Suitable for label-based alkalinity or calcium calculations. Do not use this linear calculator for pH or acid demand.</p>':''}${calc==='replacement'?'<p class="inline-note">Assumes uniform mixing and one partial replacement, not continuous drain/refill. Do not drain without checking groundwater, structural, disposal, and local restrictions.</p>':''}${calc==='saturation'?'<p class="inline-note">Independent conventional LSI estimate, not Pooli’s proprietary CSI. CYA correction interpolates the PHTA pH table only between pH 7.0 and 8.0. If borates are present or unknown, independently corrected carbonate alkalinity is required. TDS and salt are not added together. Missing essentials prevent calculation.</p><a href="https://www.phta.org/pub/?id=25A114B4-1866-DAAC-99FB-277001B3C020" target="_blank" rel="noreferrer">PHTA alkalinity correction</a> · <a href="https://poollab.poolpower.com.au/langelier/" target="_blank" rel="noreferrer">Conventional LSI equation</a>':''}`)}
function wateruse(){const readings=mine(C().meters).slice().sort((a,b)=>a.date.localeCompare(b.date));return panel('Water use, loss notes & fill timers',`<p>Record the actual meter, whether it serves only the pool, and water-level observations. Usage is not automatically classified as a leak.</p>${table(['Date / time','Meter','Cumulative gallons','Context'],readings.slice(-15).map(r=>[E(r.date.replace('T',' ')),E(r.name),fmt(r.value),E(r.scope+' · '+r.notes)]))}<form id="meterForm" class="tool-form"><div class="fields">${field('meterName','Meter name / identifier','text','','required')}${field('meterDate','Reading date & time','datetime-local','','required')}${field('meterValue','Cumulative US gallons','number','','required min="0" step="0.1"')}${select('meterScope','Meter serves',['Pool only','Shared household / unknown'],'Pool only')}${field('meterNotes','Filling, rainfall, backwash, other usage')}</div><button>Record meter</button></form><h3>Bucket-test notes</h3><form id="bucketForm" class="tool-form"><div class="fields">${field('poolDrop','Pool water-level drop (inches)','number','','required step="0.01"')}${field('bucketDrop','Bucket water-level drop (inches)','number','','required step="0.01"')}${field('bucketHours','Elapsed hours','number',24,'required min="0.01" step="0.1"')}${field('bucketNotes','Rain, splashing, pump state, limitations')}</div><button>Compare & save observation</button></form><div id="bucketResult" class="subtle"></div><h3 style="margin-top:22px">Fill timer</h3><p class="subtle">A local countdown, not an automatic shutoff. Never leave filling unattended. It cannot operate a valve or stop the hose.</p><form id="timerForm" class="tool-form"><div class="fields">${field('timerLabel','Timer label','text','Pool fill','required')}${field('timerMinutes','Minutes','number','','required min="1" max="1440"')}</div><button>Start local timer</button></form><div id="timers"></div>`)}
function weather(){const f=C().forecast;return panel('Houston weather & guided care',`<p>Default location is the Houston city center, not a sensor at your pool. Forecasts are requested only when you tap refresh. Internet access is required.</p>${button('weather','','Refresh Houston forecast')}<p class="subtle">${f?'Fetched '+E(f.fetched)+' · NWS forecast, not current pool conditions':'No forecast fetched.'}</p>${f?table(['Period','Temperature','Forecast'],f.periods.slice(0,8).map(p=>[E(p.name),E(p.temperature+' °'+p.temperatureUnit),E(p.shortForecast)])):''}<p id="weatherAdvice" class="inline-note">${f?E(weatherAdvice(f.periods)):'No weather-driven recommendation is inferred without a forecast.'}</p><h3 style="margin-top:24px">Guided follow-up</h3><p class="subtle">Rule-based checklist, not an AI diagnosis or image analysis.</p><form id="guideForm" class="tool-form">${select('guideConcern','What did you observe?',['Cloudy water','Green water / possible algae','Storm or heavy rain','Heavy swimming use','Reduced flow','Possible water loss','Bromine care'],'Cloudy water')}<button style="margin-top:14px">Show next checks</button></form><div id="guideResult"></div><p><a href="https://www.weather.gov/documentation/services-web-api" target="_blank" rel="noreferrer">National Weather Service source</a></p>`)}
function weatherAdvice(periods){const text=periods.map(p=>p.shortForecast+' '+p.detailedForecast).join(' ').toLowerCase();const advice=[];if(/rain|thunder|storm/.test(text))advice.push('Rain or storms forecast: inspect debris and water level after the event, then retest sanitizer and pH before deciding on treatment.');if(periods.some(p=>p.temperatureUnit==='F'&&p.temperature>=90))advice.push('Hot conditions forecast: monitor sanitizer demand and clarity; weather alone does not establish a dose or required pump hours.');if(periods.some(p=>p.temperatureUnit==='F'&&p.temperature<=32))advice.push('Freezing conditions forecast: follow the equipment manufacturer’s freeze-protection plan.');return advice.join(' ')||'Use actual pool observations and measurements to decide whether care needs changing. No chemical dose is inferred from this forecast.'}
function coverage(){return panel('Capability coverage',`<p>PoolMarshall is an independent app. This toolkit is based on publicly described owner workflows, not a connection to Pooli or a copy of its code, assets, product catalog, or models.</p>${table(['Workflow','Implemented here'],[['Manual chemistry tests','Extended readings, photos, configurable targets, explicit lookback, reports, CSV/share'],['Supply costs','Stock, restock thresholds, use transactions, monthly priced totals'],['Treatments','Ordered label-based steps, partial progress, awaiting retest'],['Schedules','In-app reminders and calendar export; no background push'],['Equipment','Unknown / inspected states, serials, warranties, service notes, filter baseline, feeder history'],['Calculators','Pool volume, dry ppm arithmetic, product-label ppm dose, partial replacement, fill duration, adjusted conventional LSI'],['Water loss','Meter-rate comparisons and bucket-test observations; never auto-confirmed leaks'],['Offline','Cached shell after first use; Pi edits queue locally with revision conflict protection. Browser secure context required for service worker.'],['Calibrated strip scanner','Not implemented: no licensed/calibrated model or correction-card data. Photos remain manual records.'],['Pooli proprietary CSI','Not reproduced. Independent conventional LSI estimate identifies assumptions.'],['AI / Percy / image diagnosis','Not integrated. Guided checklists are explicitly rule-based.'],['Pooli community / membership / service sharing','Not integrated. Local report sharing and exports are available.'],['Hardware','Existing AqualinkD bridge remains optional and locked by default; no chemical dosing hardware.']])}<a href="https://pooli.app/features/" target="_blank" rel="noreferrer">Reviewed owner-feature reference</a>`)}
function render(){const active=P();$('activePool').innerHTML=C().profiles.map(p=>`<option value="${E(p.id)}" ${p.id===active.id?'selected':''}>${E(p.name)}</option>`).join('');$('poolSize').textContent=fmt(active.gallons,0)+' US gal · '+active.type;$('toolHomeDue').textContent=mine(C().reminders).filter(r=>r.due<=now()).length+' reminders due · '+mine(C().products).filter(p=>p.quantity<=p.threshold).length+' supplies at restock threshold';$('waterSummary').textContent=tests().length?tests().length+' tests recorded for '+active.name+'. Open the report to see targets, prior-test labels, trends, and photos.':'No chemistry measurements recorded for '+active.name+'.';document.querySelector('header>small').innerHTML=E(active.name)+'<br>'+fmt(active.gallons,0)+' gallon '+active.type.toLowerCase();const hp=$('overview').querySelector('.poolcard>p');if(hp)hp.textContent=fmt(active.gallons,0)+' gallons · '+active.name;const views={report:()=>panel('Water report',report()),profiles:profileView,supplies,treatments,reminders,equipment,trends,calculators,wateruse,weather,coverage};$('toolContent').innerHTML=views[$('toolSelect').value]();for(const id of ['trendParam','trendDays','calcType'])if($(id))$(id).onchange=render;updateTimers();}
sec.addEventListener('submit',e=>{e.preventDefault();try{const f=e.target,values=Object.fromEntries(new FormData(f)),n=(key,min=0,max=Infinity)=>M.number(values[key],key,min,max),item={id:uid(),pool:P().id,date:now()};switch(f.id){
case 'profileForm':{P().name=values.profileName;P().gallons=n('profileGallons',1);P().type=values.profileType;P().sanitizer=values.profileSanitizer;P().finish=values.profileFinish;P().lookback=n('lookback',1,90);const targets={};for(const [k]of fields){const min=values['target-'+k+'-min'],max=values['target-'+k+'-max'],pref=values['target-'+k+'-preferred'];if(min!==undefined&&(min!==''||max!=='')){const a=M.number(min,'target minimum',0),b=M.number(max,'target maximum',a);const preferred=pref===''?'':M.number(pref,'preferred target',a,b);targets[k]={min:a,max:b,preferred};}}P().targets=targets;break;}
case 'newProfileForm':{const p={id:uid(),name:values.newName,gallons:n('newGallons',1),type:values.newType,sanitizer:'Other / unknown',finish:'Unknown',targets:{},lookback:30};C().profiles.push(p);app.save();switchPool(p.id);return;}
case 'productForm':{const price=values.price===''?null:n('price'),pack=values.packSize===''?null:n('packSize',.001);if(price!=null&&!pack)throw Error('Enter package size to calculate unit cost.');C().products.push({...item,name:values.productName,unit:values.productUnit,quantity:n('quantity'),threshold:n('threshold'),location:values.location,ingredient:values.ingredient,strength:values.strength,unitCost:price==null?null:price/pack});break;}
case 'treatmentForm':C().treatments.push({...item,title:values.treatmentTitle,product:values.treatmentProduct,planned:n('planned',.001),added:0,unit:values.treatmentUnit,order:n('order',1),retest:values.retest,wait:values.wait,instructions:values.instructions,status:'Planned'});C().treatments.sort((a,b)=>a.order-b.order);break;
case 'reminderForm':C().reminders.push({...item,title:values.reminderTitle,due:values.reminderDue,repeat:n('repeat'),notes:values.reminderNotes});break;
case 'equipmentForm':{if(values.manual&&!/^https?:\/\//i.test(values.manual))throw Error('Documentation URL must use http or https.');C().equipment.push({...item,name:values.equipmentName,model:values.model,serial:values.serial,installed:values.installed,warranty:values.warranty,baseline:values.baseline===''?'':n('baseline'),manual:values.manual,condition:values.condition,notes:values.equipmentNotes});break;}
case 'feederForm':C().feeders.push({...item,name:values.feederName,setting:values.feederSetting,date:values.feederDate,notes:values.feederNotes});break;
case 'meterForm':{const value=n('meterValue'),older=mine(C().meters).filter(x=>x.name===values.meterName&&x.date<values.meterDate).sort((a,b)=>b.date.localeCompare(a.date))[0];let notes=values.meterNotes;if(older){if(value<older.value)throw Error('Meter reading decreased; record a reset or use a new meter name.');const hours=(new Date(values.meterDate)-new Date(older.date))/36e5;notes+=' · '+fmt(M.meter(older.value,value,hours))+' gal/day average over '+fmt(hours)+' hours; '+(values.meterScope==='Pool only'?'usage is not a confirmed leak':'household uses included');}C().meters.push({...item,name:values.meterName,date:values.meterDate,value,scope:values.meterScope,notes});break;}
case 'bucketForm':{const excess=(n('poolDrop',-100)-n('bucketDrop',-100))/n('bucketHours',.01)*24;state().logs.unshift({kind:'Water-loss observation',logdate:now(),fc:'',ph:'',temp:'',psi:'',cya:'',flow:'',lognotes:'Pool minus bucket drop: '+fmt(excess)+' inches/day. '+(excess>0?'Possible excess loss; needs repeat testing.':'No positive excess indicated by these inputs.')+' '+values.bucketNotes,logfollow:'Verify rain, splashing, levels and test conditions. No leak confirmed.'});break;}
case 'timerForm':C().timers.push({...item,label:values.timerLabel,end:Date.now()+n('timerMinutes',1,1440)*60000});break;
case 'calculatorForm':{let result;switch(f.dataset.kind){case 'volume':result=fmt(M.volume(values.shape,values.length,values.width,values.shallow,values.deep),0)+' estimated US gallons. The profile volume has not been changed.';break;case 'dry':result=fmt(M.dryDose(n('doseGallons',1),n('currentPPM'),n('targetPPM'),n('purity',.01,100)),1)+' grams of dry product ('+fmt(M.dryDose(n('doseGallons',1),n('currentPPM'),n('targetPPM'),n('purity',.01,100))/28.349523125,2)+' oz by weight). '+values.doseParam+' mass-balance estimate only; verify label and active basis.';break;case 'label':result=fmt(M.labelDose(P().gallons,n('desiredChange'),n('labelAmount',.001),n('labelGallons',1),n('labelChange',.001)),3)+' '+values.labelUnit+' estimated from the entered label ratio. Only for the stated ppm rise; not pH dosing.';break;case 'replacement':result=fmt(M.dilution(n('replaceCurrent'),n('replaceSource'),n('replacePercent',0,100)/100))+' ppm after one '+values.replacePercent+'% partial replacement ('+fmt(P().gallons*n('replacePercent')/100,0)+' gallons). Structural and local restrictions not evaluated.';break;case 'flow':result=fmt(n('fillGallons',1)/n('fillGPM',.01),1)+' minutes at the entered constant flow. Observe the fill; no automatic shutoff.';break;case 'saturation':{const ph=n('lsiPH',6,9);let ca;if(values.lsiCA!=='')ca=n('lsiCA',1);else{if(values.lsiBorates!=='Verified absent')throw Error('Enter independently corrected carbonate alkalinity when borates are present or unknown.');ca=M.carbonate(n('lsiTA',1),n('lsiCYA'),ph);}const index=M.lsi(ph,n('lsiTemp',32,110),n('lsiCH',1),ca,n('lsiTDS',1));result='Adjusted conventional LSI: '+index.toFixed(2)+' · carbonate alkalinity '+fmt(ca)+' ppm. '+(index>.3?'Elevated calcium-carbonate scaling tendency estimate.':index<-.3?'Undersaturation / dissolution tendency estimate.':'Near the conventional ±0.3 reference band.')+' This is not thermodynamic CSI, a metal-corrosion guarantee, or swimming-safety approval. '+(values.lsiCA!==''?'Carbonate alkalinity supplied independently.':'CYA correction interpolated from the PHTA pH table; borates asserted absent.');break;}}$('calcResult').textContent=result;return;}
case 'guideForm':{const advice={'Bromine care':'Measure bromine and pH with a compatible test kit. Follow the bromine product and feeder instructions, including any oxidation procedure and retesting. Do not apply chlorine-only/CYA dosing assumptions to bromine care; the app does not calculate a bromine or oxidation dose.','Cloudy water':'Measure current sanitizer and pH. Record clarity, recent additions, filter pressure against a verified clean baseline, and circulation observations. Do not infer a chemical dose or safe swimming from appearance.','Green water / possible algae':'Record color and surface texture, then measure sanitizer, pH and CYA. Brushing and inspection may be useful. Appearance alone cannot distinguish algae from metals; verify the cause before treatment.','Storm or heavy rain':'After conditions are safe, inspect debris and water level and retest sanitizer and pH. Use the new measurements and product label before planning treatment.','Heavy swimming use':'Retest sanitizer and pH more frequently and log changes. Demand varies; bather count alone is not a dosing formula.','Reduced flow':'Check water level, basket debris and measured filter pressure against a verified baseline. Air, obstruction or equipment faults are possibilities; record evidence before confirming a fault.','Possible water loss':'Compare consistent water-level observations with evaporation, rain, splashing, backwashing and known filling. Use the bucket-test and meter records; an excess is a warning to investigate, not a confirmed leak.'};$('guideResult').textContent=advice[values.guideConcern];return;}
default:return;
}store();app.render();message('Record saved for '+P().name+'.');}catch(err){message(err.message)}});
sec.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;try{switch(action){case 'tool':openTool(id);return;case 'share-report':{const text=reportText();if(navigator.share)await navigator.share({title:P().name+' water report',text});else if(navigator.clipboard){await navigator.clipboard.writeText(text);message('Report copied.');}else saveText('poolmarshall-water-report.txt',text);return;}
case 'export-tests':saveText('poolmarshall-tests.csv',csv([['Pool','Date','Method',...fields.map(f=>f[1]),'Notes'],...tests().map(t=>[P().name,t.logdate,t.method,...fields.map(([k])=>t[k]??''),t.lognotes])]),'text/csv');return;
case 'export-costs':saveText('poolmarshall-supply-usage.csv',csv([['Pool','Date','Product','Type','Amount','Unit','Cost','Notes'],...mine(C().transactions).map(t=>[P().name,t.date,t.name,t.kind,t.amount,t.unit,t.unitCost==null?'':t.amount*t.unitCost,t.notes])]),'text/csv');return;
case 'edit-product':{const p=C().products.find(p=>p.id===id),stock=prompt('Reconciled stock in '+p.unit,p.quantity);if(stock===null)return;const threshold=prompt('Restock threshold in '+p.unit,p.threshold);if(threshold===null)return;const price=prompt('Price PER ONE '+p.unit+' in dollars. Blank means unknown.',p.unitCost??'');if(price===null)return;const quantity=M.number(stock,'stock',0),limit=M.number(threshold,'threshold',0),unitCost=price===''?null:M.number(price,'unit price',0);if(quantity!==p.quantity)C().transactions.push({id:uid(),pool:P().id,date:now(),product:p.id,name:p.name,kind:'Stock reconciliation',amount:quantity-p.quantity,unit:p.unit,unitCost:null,notes:'Manual stock count; not usage.'});p.quantity=quantity;p.threshold=limit;p.unitCost=unitCost;break;}
case 'use-product':case 'restock-product':{const p=C().products.find(p=>p.id===id);const raw=prompt((action==='use-product'?'Amount used':'Amount restocked')+' in '+p.unit);if(raw===null)return;const amount=M.number(raw,'amount',.001);if(action==='use-product'&&amount>p.quantity)throw Error('Amount exceeds recorded stock. Reconcile stock first.');const note=prompt('Usage/restock notes (optional)')||'';p.quantity+=action==='use-product'?-amount:amount;C().transactions.push({id:uid(),pool:P().id,date:now(),product:p.id,name:p.name,kind:action==='use-product'?'Use':'Restock',amount,unit:p.unit,unitCost:p.unitCost,notes:note});break;}
case 'advance-treatment':{const t=C().treatments.find(t=>t.id===id),raw=prompt('Additional amount actually added, in '+t.unit+'. Log inventory use separately.');if(raw===null)return;const amount=M.number(raw,'amount',.001);if(t.added+amount>t.planned)throw Error('Amount exceeds this plan. Review the plan before adding more.');t.added+=amount;t.status=t.added>=t.planned?'Awaiting retest':'Partly added';t.lastAdded=stamp();break;}
case 'retest-treatment':{const t=C().treatments.find(t=>t.id===id);if(!confirm('Confirm you actually retested the water. This does not certify swimming safety.'))return;t.status='Retested; review results';t.retested=stamp();break;}
case 'complete-reminder':{const r=C().reminders.find(r=>r.id===id);state().logs.unshift({kind:'Maintenance reminder completed',logdate:now(),fc:'',ph:'',temp:'',psi:'',cya:'',flow:'',lognotes:r.title+' · '+r.notes,logfollow:''});if(r.repeat){r.lastCompleted=now();r.due=dateAdd(now(),r.repeat)}else C().reminders=C().reminders.filter(x=>x.id!==id);break;}
case 'snooze-reminder':{const r=C().reminders.find(r=>r.id===id);r.due=dateAdd(r.due,7);break;}
case 'calendar-reminder':{const r=C().reminders.find(r=>r.id===id),escape=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,'\\$&');saveText('poolmarshall-reminder.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//CodedThought//PoolMarshall//EN','BEGIN:VEVENT','UID:'+r.id+'@poolmarshall.local','DTSTAMP:'+stamp().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;VALUE=DATE:'+r.due.replace(/-/g,''),'SUMMARY:'+escape(r.title),'DESCRIPTION:'+escape(P().name+' · '+r.notes),...(r.repeat?['RRULE:FREQ=DAILY;INTERVAL='+r.repeat]:[]),'END:VEVENT','END:VCALENDAR'].join('\r\n'),'text/calendar');return;}
case 'equipment-note':{const q=C().equipment.find(x=>x.id===id),note=prompt('Service observation, with measurements and units. Do not claim inspection unless performed.');if(!note)return;q.notes+=(q.notes?'\n':'')+now()+': '+note;state().logs.unshift({kind:'Equipment service note',logdate:now(),fc:'',ph:'',temp:'',psi:'',cya:'',flow:'',lognotes:q.name+' · '+note,logfollow:''});break;}
case 'stop-timer':C().timers=C().timers.filter(t=>t.id!==id);break;
case 'weather':{message('Requesting forecast…');let response;if(app.hosted){const points=await fetch('https://api.weather.gov/points/29.7604,-95.3698');if(!points.ok)throw Error('NWS unavailable. Prior forecast, if any, is retained.');const meta=await points.json(),f=await fetch(meta.properties.forecast);if(!f.ok)throw Error('Forecast unavailable.');response=await f.json();response={periods:response.properties.periods};}else{const r=await fetch('/api/weather');if(!r.ok)throw Error('Weather service unavailable. The Pi needs internet access; prior data is retained.');response=await r.json();}C().forecast={fetched:stamp(),periods:response.periods};break;}
}store();app.render();}catch(err){message(err.name==='AbortError'?'Share cancelled.':err.message)}});
function updateTimers(){const box=$('timers');if(!box)return;box.innerHTML=list(mine(C().timers).map(t=>{const remaining=Math.max(0,t.end-Date.now()),seconds=Math.floor(remaining/1000);return `<div class="row"><div class="body"><h3>${E(t.label)}</h3><p>${remaining?Math.floor(seconds/60)+'m '+seconds%60+'s remaining':'Time reached: check the fill now. No shutoff occurred.'}</p></div>${button('stop-timer',t.id,'Dismiss')}</div>`}),'No active fill timers.')}
setInterval(updateTimers,1000);
if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});
app.onChange=()=>{if(!$('tools').classList.contains('hidden'))render();};
render();app.save();
}
if(window.Poolside)boot();else document.addEventListener('poolside-ready',boot,{once:true});
})();
